	public OrionAstrarium GetOrionAstrarium(GameObject source)
	{
		if (source != null && source.TryGetComponent<CorruptedAnimalSpriteControl>(out var component))
		{
			return component.OrionAstrarium;
		}
		return PlayerGameObject.GetComponent<PlayerEffects>().OrionAstrarium;
	}

	public void PurgingIncenseActivated()
