	private void Start()
	{
		playerCorruptionStats = PlayerGameObject.GetComponent<PlayerCorruptionStats>();
		playerEffects = PlayerGameObject.GetComponent<PlayerEffects>();
		playerSpriteControl = PlayerGameObject.GetComponent<PlayerSpriteControl>();
	}

	public void InitializeBattle(bool ambushBattle, bool resetDiceBadAndDiscard, bool dontPickCorruptedAnimalsToBattle = false)
	{
		justDiscardedDice = null;
		CorruptedSoulActivated = false;
		OnHideHeartIcon.Raise();
		OnEnableTurnCounterText.Raise();
		OnEnableDrawPoolAndDiscardCounterText.Raise();
		if (resetDiceBadAndDiscard)
		{
			diceBag.SetInventoryItems(allDiceBag.InventoryItems);
			discard.OnResetToStartRunState();
		}
		ReferenceSingleton<TurnManager>.Instance.InitializeBattle(ambushBattle);
		InvokeAlternatives.InvokeAfterMultipleFrames(this, 10, delegate
		{
			ReferenceSingleton<PlayerDiceHandHolder>.Instance.InitializeBattle();
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.InitializeBattle();
			ReferenceSingleton<GameStateManager>.Instance.InitializeBattleResetGameStateSOs();
			if (!dontPickCorruptedAnimalsToBattle)
			{
				PickCorruptedAnimalsToBattle();
			}
			InvokeAlternatives.InvokeAfterMultipleFrames(this, 3, delegate
			{
				if (initializingBattleFromContinue)
				{
					initializingBattleFromContinue = false;
					InvokeAlternatives.Invoke(this, 0.5f, delegate
					{
						InitializeBattleGameStateManager();
					});
				}
				else
				{
					InitializeBattleGameStateManager();
				}
			});
		});
	}

	private void InitializeBattleGameStateManager()
	{
		if (IsOnAstreaFirstPhaseBattle())
		{
			Debug.Log("IsOnAstreaFirstPhaseBattle()");
			StartCoroutine(astreaFirstPhaseSplittingHandler.AstreaSplittingAnimation());
		}
		else
		{
			ReferenceSingleton<GameStateManager>.Instance.InitializeBattle();
		}
	}

	public bool IsOnAstreaFirstPhaseBattle()
	{
		Debug.Log("---****----mapHandler.IsOnAstreasHeart: " + mapHandler.IsOnAstreasHeart);
		Debug.Log("---****----mapHandler.BossBattle: " + mapHandler.BossBattle);
		Debug.Log("---****----AssetsReference.Instance.PlayerRunData.AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase: " + ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase);
		Debug.Log("---****----IsOnAstreaFirstPhaseBattle: " + (mapHandler.IsOnAstreasHeart && mapHandler.BossBattle && !ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase));
		if (mapHandler.IsOnAstreasHeart && mapHandler.BossBattle)
		{
			return !ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase;
		}
		return false;
	}

	[Button(null)]
	public void PickCorruptedAnimalsToBattle()
	{
		if (!currentBattleCorruptedAnimals.DebugBattle)
		{
			CheckFirstTimePlayingWithMoonieEnemyOverride();
			CheckHiddenAnomalyLevelEnemyOverride();
			currentCorruptedAnimals.StoreAllCorruptedAnimals();
			if (!forcedCurrentBattleCorruptedAnimals)
			{
				List<CorruptedAnimalData> list = battleCorruptedAnimalsList.GetEnemyPackage(mapHandler.CurrentNodeData.BattlePackage).CorruptedAnimals.DuplicateAsList();
				currentBattleCorruptedAnimals.CorruptedAnimals = list.ToArray();
			}
		}
		else if (currentBattleCorruptedAnimals.Package)
		{
			List<CorruptedAnimalData> list2 = currentBattleCorruptedAnimals.battleCorruptedAnimalsPackage.CorruptedAnimals.DuplicateAsList();
			currentBattleCorruptedAnimals.CorruptedAnimals = list2.ToArray();
		}
		OnPopulateEnemies.Raise();
		ReferenceSingleton<MenuManagerCanvasGroup>.Instance.SetOnIsOnBattle(value: true);
		forcedCurrentBattleCorruptedAnimals = false;
	}

	private void CheckFirstTimePlayingWithMoonieEnemyOverride()
	{
		if (IsFirstTimePlayingWithMoonie() && ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == playerProgressionData.MoonieCharacter && mapHandler.CurrentAreaIndex == 0)
		{
			string text = "";
			if (mapHandler.CurrentAreaLevelIndex == 0)
			{
				text = playerProgressionData.FirstBattleOverrideCorruptedAnimalPackageName;
			}
			else if (mapHandler.CurrentAreaLevelIndex == 2)
			{
				text = playerProgressionData.SecondBattleOverrideCorruptedAnimalPackageName;
			}
			else if (mapHandler.CurrentAreaLevelIndex == 5)
			{
				text = ((mapHandler.CurrentNodeData.NodeEnum != NodeEnum.BATTLEHARD) ? playerProgressionData.ThirdBattleOverrideCorruptedAnimalPackageName : playerProgressionData.ThirdBattleHardOverrideCorruptedAnimalPackageName);
			}
			if (text != string.Empty)
			{
				SetForcedCurrentBattleCorruptedAnimals(battleCorruptedAnimalsList.GetEnemyPackage(text));
			}
		}
	}

	private bool IsFirstTimePlayingWithMoonie()
	{
		if (!gameController.IsDemo)
		{
			if (playerProgressionData.MoonieCharacter.CharacterProgression.CharacterXP == 0)
			{
				return true;
			}
		}
		else if (playerProgressionData.FirstTimePlayingWithMoonieDemo)
		{
			return true;
		}
		return false;
	}

	private void CheckHiddenAnomalyLevelEnemyOverride()
	{
		if (mapHandler.BossBattle && ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HiddenAnomalyLevelFirstBossDefeatedStartBattleOnSecondBoss)
		{
			SetForcedCurrentBattleCorruptedAnimals(battleCorruptedAnimalsList.GetEnemyPackage(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HiddenAnomalyLevelSecondBossPackageName));
		}
	}

	public void SetForcedCurrentBattleCorruptedAnimals(BattleCorruptedAnimals battleCorruptedAnimals)
	{
		currentBattleCorruptedAnimals.CorruptedAnimals = battleCorruptedAnimals.CorruptedAnimals.Duplicate();
		forcedCurrentBattleCorruptedAnimals = true;
	}

	public void EndOfBattleInitialize()
	{
		playerEffects.EndOfBattleInitialize();
		currentCorruptedAnimals.StoreAllCorruptedAnimals();
		currentCompanions.EndOfBattleInitialize();
		playerCorruptionStats.EndOfBattleInitialize();
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartOmensEndOfBattle();
		OnEndOfBattleInitialize.Raise();
		allDiceBag.ResetAllMagnetizedDice();
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.SetDefaultDrawDicesAmount();
		ReferenceSingleton<MenuManagerCanvasGroup>.Instance.SetOnIsOnBattle(value: false);
		ReferenceSingleton<RunModifiersManager>.instance.EndOfBattleInitialize();
	}

	public void BeforeActionCasted()
	{
		currentActionInstance.ActionFace.BattleAction.BeforeActionCasted();
		if (currentActionInstance is DiceInstance)
		{
			DiceInstance diceInstance = currentActionInstance as DiceInstance;
			ReferenceSingleton<MiscOmensHandler>.Instance.ActivateOnDiceUsedOmensBeforeCast(diceInstance.Dice);
			OnSpecificDiceCastedBeforeActionCasted.Raise(diceInstance.Dice);
		}
		bool flag = false;
		if (currentActionInstance.ActionFace.EnableSecondAction)
		{
			flag = currentActionInstance.ActionFace.SecondBattleAction.DisableAutoDisposeAsSecondAction;
		}
		if (currentActionInstance.ActionFace.BattleAction.DisableAutoDispose || flag || !(currentActionInstance is DiceInstance))
		{
			return;
		}
		DiceInstance diceInstance2 = currentActionInstance as DiceInstance;
		if (diceInstance2.DiceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			if (!currentActionInstance.ActionFace.BattleAction.OncePerBattle && diceInstance2.Dice.DiceTier != hexDiceTier)
			{
				playerEffects.CheckSandsOfTime();
			}
		}
		else if (playerEffects.SandsOfTimeExtraChance == 100)
		{
			playerEffects.CheckSandsOfTime();
		}
		else if (ReferenceSingleton<SothisOmensHandler>.Instance.IsHourglassModuleOmenActive())
		{
			playerEffects.CheckSandsOfTime();
		}
		else
		{
			playerEffects.ResetVariablesBeforeCheckSandsOfTime();
		}
	}

	public void ActionCasted()
	{
		if (currentActionInstance.DiceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			playerSpriteControl.PlayAttackOrSkillAnimation();
		}
		else
		{
			currentActionInstance.ActionOwner.GetComponent<CompanionAbility>().PlayActivationAnimation();
		}
		bool flag = false;
		ActionFace actionFace = currentActionInstance.ActionFace;
		if (actionFace.BattleAction.CancelAutoOnDiceCastedOnRuneCasted)
		{
			flag = true;
		}
		else if (actionFace.EnableSecondAction && actionFace.SecondBattleAction.CancelAutoOnDiceCastedOnRuneCasted)
		{
			flag = true;
		}
		if (!flag)
		{
			OnDiceCastedOrOnRuneCasted();
		}
		bool flag2 = false;
		if (currentActionInstance is DiceInstance)
		{
			bool flag3 = false;
			if (currentActionInstance.ActionFace.EnableSecondAction)
			{
				flag3 = currentActionInstance.ActionFace.SecondBattleAction.DisableAutoDisposeAsSecondAction;
			}
			DiceInstance diceInstance = currentActionInstance as DiceInstance;
			if (currentActionInstance.ActionFace.BattleAction.DisableAutoDispose || flag3)
			{
				flag2 = true;
				if (diceInstance.DiceOwnerEnum == DiceOwnerEnum.COMPANION && (currentActionInstance.ActionFace.BattleAction is InvokeAction || (currentActionInstance.ActionFace.EnableSecondAction && currentActionInstance.ActionFace.SecondBattleAction is PurgeAction)))
				{
					flag2 = false;
				}
			}
		}
		if (!flag2)
		{
			if (currentActionInstance is DiceInstance)
			{
				DiceInstance diceInstance2 = currentActionInstance as DiceInstance;
				if (diceInstance2.DiceOwnerEnum == DiceOwnerEnum.PLAYER)
				{
					if (!currentActionInstance.ActionFace.BattleAction.OncePerBattle)
					{
						if (diceInstance2.Dice.DiceTier == hexDiceTier)
						{
							if (!purgingIncenseActivated && !currentCorruptedAnimals.IsAnyWithEnemyCursedSandsCheckCursedSands(diceInstance2))
							{
								currentActionInstance.DisposeAction();
							}
						}
						else if (!playerEffects.IsSandsOfTimeTriggeredTriggerIt(diceInstance2))
						{
							currentActionInstance.DisposeAction();
						}
					}
					else
					{
						currentActionInstance.DisposeAction();
					}
				}
				else if (!diceInstance2.ConsumeIgnoreNextDisposeAction() && !playerEffects.IsSandsOfTimeTriggeredTriggerIt(diceInstance2))
				{
					currentActionInstance.DisposeAction();
				}
			}
			else
			{
				currentActionInstance.DisposeAction();
			}
		}
		currentActionInstance = null;
		purgingIncenseActivated = false;
	}

	public void OnDiceCastedOrOnRuneCasted()
	{
		if (lateCurrentActionInstance is DiceInstance)
		{
			DiceInstance diceInstance = lateCurrentActionInstance as DiceInstance;
			OnSpecificDiceCasted.Raise(diceInstance.Dice);
			ReferenceSingleton<MiscOmensHandler>.Instance.ActivateOnDiceUsedOmens(diceInstance.Dice);
			ReferenceSingleton<RunModifiersManager>.Instance.ActivateOnDicePlayedRunModifiers(diceInstance.Dice);
			if (!endlessTricksAchievementData.IsUnlocked())
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.DiceUsedAmount++;
				if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.DiceUsedAmount >= endlessTricksAchievementData.AchievementVariableAmount)
				{
					endlessTricksAchievementData.Unlock();
				}
			}
			return;
		}
		RuneInstance runeInstance = lateCurrentActionInstance as RuneInstance;
		List<GameObject> activeCorruptedAnimals = currentCorruptedAnimals.activeCorruptedAnimals;
		for (int i = 0; i < activeCorruptedAnimals.Count; i++)
		{
			activeCorruptedAnimals[i].GetComponent<UnitEffects>().OnRuneCasted(runeInstance);
		}
		PlayerGameObject.GetComponent<UnitEffects>().OnRuneCasted(runeInstance);
		List<GameObject> activeCompanions = ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.ActiveCompanions;
		for (int j = 0; j < activeCompanions.Count; j++)
		{
			activeCompanions[j].GetComponent<UnitEffects>().OnRuneCasted(runeInstance);
		}
		ReferenceSingleton<MiscOmensHandler>.Instance.ActivateVirtueOmens();
		ReferenceSingleton<RunModifiersManager>.Instance.ActivateOnVirtuePlayedRunModifier();
		if (!virtuousWarriorAchievementData.IsUnlocked())
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.VirtuesUsedAmount++;
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.VirtuesUsedAmount >= virtuousWarriorAchievementData.AchievementVariableAmount)
			{
				virtuousWarriorAchievementData.Unlock();
			}
		}
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.VirtuesUsedAmount++;
	}

	public void SetActionDescriptionActionInstance(ActionInstance actionDescriptionActionInstance)
	{
		this.actionDescriptionActionInstance = actionDescriptionActionInstance;
	}

	public void SetCurrentActionInstance(ActionInstance currentActionInstance)
	{
		this.currentActionInstance = currentActionInstance;
		if (currentActionInstance != null)
		{
			lateCurrentActionInstance = currentActionInstance;
		}
	}

	public bool IsSourcePlayerOrCompanionsCurrentActionInstance()
	{
		if (!(currentActionInstance.ActionOwner == PlayerGameObject))
		{
			return currentCompanions.ActiveCompanions.Contains(currentActionInstance.ActionOwner);
		}
		return true;
	}

	public bool IsSourcePlayer(GameObject source)
	{
		return source == PlayerGameObject;
	}

	public bool IsSourcePlayerOrCompanions(GameObject source)
	{
		if (!IsSourcePlayer(source))
		{
			return currentCompanions.ActiveCompanions.Contains(source);
		}
		return true;
	}

	public bool IsSourceCompanions(GameObject source)
	{
		return currentCompanions.ActiveCompanions.Contains(source);
	}

	public bool IsSourceEnemy(GameObject source)
	{
		return currentCorruptedAnimals.activeCorruptedAnimals.Contains(source);
	}

	public bool IsTargetEnemy(GameObject target)
	{
		return currentCorruptedAnimals.activeCorruptedAnimals.Contains(target);
	}

	public bool IsTargetSentinel(GameObject target)
	{
		return currentCompanions.ActiveCompanions.Contains(target);
	}

	public bool IsTargetPlayer(GameObject target)
	{
		return target == PlayerGameObject;
	}

	public void OnMouseOverEndTurn()
	{
		bool flag = false;
		bool flag2 = false;
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == playerProgressionData.MoonieCharacter && playerProgressionData.MoonieCharacter.CharacterProgression.CharacterXP == 0 && mapHandler.CurrentAreaIndex == 0 && playerCurrentRunes.IsAnyPlayableNonMustUseActions())
		{
			flag = true;
		}
		if (!ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.DisableSentinelDiceTutorialRunWarning && currentCompanions.RuntimeCompanions.Count > 0 && currentCompanions.IsAnyPlayableNonMustUseActions())
		{
			flag2 = true;
		}
		string text = "";
		if (flag && flag2)
		{
			text = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("SentinelsDieNotUsedWarning") + "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("VirtuesNotUsedWarning");
		}
		else if (flag)
		{
			text = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("VirtuesNotUsedWarning");
		}
		else if (flag2)
		{
			text = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("SentinelsDieNotUsedWarning");
		}
		if (text != "")
		{
			OnShowThenHideDialogueCustomizedPlayer.Raise(text);
		}
	}

	public void OnStartChooseActionState()
	{
		if (!ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HandLimitWarningShowedInThisRun && (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() == 6 || ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() == 7))
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HandLimitWarningShowedInThisRun = true;
			OnShowThenHideDialogueCustomizedPlayer.Raise(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("MyHandIsAboutToGetFull"));
		}
		if (!ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HandFullWarningShowedInThisRun && ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() == ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.HandLimit)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HandFullWarningShowedInThisRun = true;
			OnShowThenHideDialogueCustomizedPlayer.Raise(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("MyHandIsFull"));
		}
	}
